sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
	//Scratchpad variables
    var gURI = new GlideURI();
    var list_query = gURI.get('sysparm_record_list');
    var number_rows = gURI.get('sysparm_record_rows');
    //gs.info(list_query);
    g_scratchpad.query = list_query;
    g_scratchpad.host = gs.getProperty("glide.servlet.uri");
    g_scratchpad.rows = number_rows;
	g_scratchpad.name = current.assigned_to ? current.assigned_to.first_name: '';
	g_scratchpad.time = GlideDateTime().getDisplayValue();
	g_scratchpad.usr_access = gs.getUser().isMemberOf(current.assignment_group.parent.toString());	//MSSCUSTODY-4911
	g_scratchpad.hasWorkedAsMaker = false;	//MSSCUSTODY-4911

	//MSSCUSTODY-4911
	if (current.lock == false && (current.state == '1' || current.state == '2') && gs.getUser().isMemberOf(current.assignment_group.parent.toString()) && (current.trade_task_type == 'Checker' || current.trade_task_type == 'Maker' )) {

		if(current.trade_task_type == 'Checker'){
			if(current.trade_case_id.current_maker_assignee == gs.getUserID()){    //If current user has been a Maker before
				g_scratchpad.hasWorkedAsMaker = true;
				return;
			}
			current.assigned_to = gs.getUserID();
            current.lock = true; 
            current.locktime = GlideDateTime().getDisplayValue();         
            current.update();
		}

        else{
            current.assigned_to = gs.getUserID();
            current.lock = true; 
            current.locktime = GlideDateTime().getDisplayValue();         
            current.update();
        }

    }

	//MSSCUSTODY - 5540 : Checks if a user has already worked as a maker on a checker task for a Work in Progress checker task
	else if(current.lock == true && current.state == '2' && gs.getUser().isMemberOf(current.assignment_group.parent.toString()) && current.trade_task_type == 'Checker' && current.trade_case_id.current_maker_assignee == gs.getUserID()){
		g_scratchpad.hasWorkedAsMaker = true;
		return;

	}

})(current, previous);
